function frequencyAtValue(parameter){
  const points=(parameter.scale||[]).map(p=>({value:p.value,hz:physicalFrequency(p)})).filter(p=>p.hz>0).sort((a,b)=>a.value-b.value);
  if(points.length<2)return physicalFrequency(parameter);
  const value=clamp(parameter.value,points[0].value,points.at(-1).value);
  for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i];if(value<=b.value)return a.hz*(b.hz/a.hz)**((value-a.value)/(b.value-a.value));}
  return points.at(-1).hz;
}
