function valueAtFrequency(parameter, hz) {
  const samples = (parameter.scale || [])
    .map((p) => ({ value: p.value, hz: physicalFrequency(p) }))
    .filter((p) => p.hz > 0)
    .sort((a, b) => a.hz - b.hz);
  if (samples.length < 2) return null;
  hz = clamp(hz, samples[0].hz, samples.at(-1).hz);
  for (let i = 1; i < samples.length; i++) {
    const a = samples[i - 1],
      b = samples[i];
    if (hz <= b.hz)
      return (
        a.value +
        ((b.value - a.value) * Math.log(hz / a.hz)) / Math.log(b.hz / a.hz)
      );
  }
  return samples.at(-1).value;
}

return {graphPlugins,responseDb,frequencyX,xFrequency,valueAtFrequency,frequencyAtValue,normalized,clamp,FILTER_DISPLAY};
